# area: self_classmethods
# hypothesis: Self-returning methods, a Self classmethod constructor and a Self property keep the calling subclass type, while passing an int to add is an error.
from typing import Self, assert_type, reveal_type


class Builder:
    def __init__(self) -> None:
        self.parts: list[str] = []

    def add(self, part: str) -> Self:
        self.parts.append(part)
        return self

    @classmethod
    def empty(cls) -> Self:
        return cls()

    @property
    def me(self) -> Self:
        return self

    def describe(self) -> str:
        return '+'.join(self.parts)


class LoudBuilder(Builder):
    def shout(self) -> Self:
        self.parts = [p.upper() for p in self.parts]
        return self


b = LoudBuilder.empty().add('a').add('b').shout()
assert_type(b, LoudBuilder)
reveal_type(b.me)
assert_type(Builder().add('x').me, Builder)
assert b.describe() == 'A+B'
plain = Builder.empty().add('q')
assert plain.describe() == 'q'
bad = Builder.empty()
bad.add(3)  # expect-error
